        /// <summary>u8, 1 B. g_disk_drive_letters[1]</summary>
        public const int Disk1DriveLetter = 0xa9c9;
        /// <summary>u8, 1 B. g_disk_drive_letters[3] (Ghidra cRam0002a00b)</summary>
        public const int Disk3DriveLetter = 0xa9cb;
        /// <summary>u8, 1 B. nonzero = PC speaker sound on (toggled by a command, set to 1 by INTRO)</summary>
        public const int SoundEnabled = 0xa9ce;
        /// <summary>u8, 1 B. status window needs redraw</summary>
        public const int StatusDirty = 0xa9fa;
        /// <summary>u8[32][8], 256 B. copy of g_monster_table for the duration of combat (part 2 named slot 1 of it at 0xaa04)</summary>
        public const int MonsterTableBackupA9fc = 0xa9fc;
        /// <summary>u8[31][8], 248 B. g_monster_table_backup_a9fc slot 1 onward (base 0xa9fc; part 2 named slot 1 here) - copy of the monster table made by run_camp_scene (base 0xa9fc; 0xa</summary>
        public const int MonsterTableBackupAa04 = 0xaa04;
        /// <summary>u8[11][32], 352 B. terrain tile of each view cell (row stride 0x20); 0 = an object is drawn there instead (see g_view_objects), 0xff = darkness</summary>
        public const int ViewTiles = 0xab02;
        /// <summary>u8[11][16], 176 B. object/NPC tile (0x100-relative) drawn at each view cell when g_view_tiles is 0 (row stride 0x10)</summary>
        public const int ViewObjects = 0xac64;
        /// <summary>u8[32][32], 1024 B. RAM: in towns the light map built by rebuild_light_map (0 = unlit, else the tile); in combat (loc&gt;=0x80) the 11x11 combat map (stride 0x20)</summary>
        public const int LightMap = 0xad14;
        /// <summary>u8, 1 B. g_light_map[5][5]; 0xdc marks a centre object</summary>
        public const int CombatMapCentre = 0xadb9;
        /// <summary>ptr, 2 B. near pointer to the SAVED.OOL buffer (0xb21e)</summary>
        public const int OolBufferPtr = 0xb11c;
        /// <summary>u8[256], 256 B. display tile for each terrain tile 0..255 (identity except the animated groups); used by draw_map_view</summary>
        public const int TileAnimMap = 0xb11e;
        /// <summary>u8[0x200], 512 B. SAVED.OOL image (object lists)</summary>
        public const int OolBuffer = 0xb21e;
        /// <summary>u8[0x100], 256 B. second half of g_ool_buffer: UNDER.OOL image (Underworld object list) written by main() after a game is loaded</summary>
        public const int OolBufferUnder = 0xb31e;
        /// <summary>u8[32][8], 256 B. combat participants: +2 flags (0x80 party member, 1/2/4/8 state bits), +3 party index or monster char, +4 monster-table slot, +6 x, +7 y (RAM only)</summary>
        public const int CombatRoster = 0xba14;
        /// <summary>u8, 1 B. roster +1: dexterity for party members, stat0 +/-3 for monsters</summary>
        public const int RosterInitiative = 0xba15;
        /// <summary>u8, 1 B. g_combat_roster +2 flags: 0x80 party member, 0x20 inactive, 0x10/0x04 (COMBAT), 0x01 charmed; stride 8</summary>
        public const int RosterFlags = 0xba16;
        /// <summary>u8, 1 B. g_combat_roster entry +3: party member index for party-side entries (monster type for monsters), stride 8</summary>
        public const int RosterMember = 0xba17;
        /// <summary>u8, 1 B. roster +4: monster-table slot of this combatant</summary>
        public const int RosterSlot = 0xba18;
        /// <summary>u8, 1 B. roster +5: 36 - initiative</summary>
        public const int RosterTurnCounter = 0xba19;
        /// <summary>u8, 1 B. g_combat_roster +6 x</summary>
        public const int RosterX = 0xba1a;
        /// <summary>u8, 1 B. g_combat_roster +7 y</summary>
        public const int RosterY = 0xba1b;
        /// <summary>u8, 1 B. RAM: wall tile of the current dungeon style, set by DUNGEON_8ffe (md part 4)</summary>
        public const int DungeonWallTile = 0xbb14;
        /// <summary>u8, 1 B. RAM: floor tile of the current dungeon style (0x45 or 5), set by DUNGEON_8ffe</summary>
        public const int DungeonFloorTile = 0xbb15;
        /// <summary>u8, 1 B. RAM: 1 when DNGLOOK applied driver_tile_patch(0); restored with command 1 after combat</summary>
        public const int TilesPatched = 0xbb16;
        /// <summary>u8, 1 B. RAM byte after g_tiles_patched: dungeon flags (DUNGEON overlay) (md part 4)</summary>
        public const int DungeonFlags = 0xbb17;
        /// <summary>u8, 1 B. RAM byte used by INTRO (md part 4); meaning not determined</summary>
        public const int IntroFlagBb18 = 0xbb18;
        /// <summary>u8[0x800], 2048 B. end of the DATA.OVL image (file size 0xbd50 -&gt; DGROUP 0xbd40). crt0 sets SP = 0xbd3e per the ROOT analysis while ARCHITECTURE.md places BSS+stack at 0</summary>
        public const int Stack = 0xbd40;
    }
}
